"""Tests for bulk discount calculation.

These tests verify the bulk discount rules: 5% discount on line items
with quantity >= 10, rounded half-up to cents.
"""

from decimal import Decimal

import pytest

from pricing import LineItem, qualifies_for_bulk_discount, calculate_bulk_discount


class TestBulkDiscountThreshold:
    """Tests for the bulk discount quantity threshold."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_10_qualifies_for_bulk_discount(self):
        """Quantity of exactly 10 should qualify for bulk discount. (Req 1.1)"""
        item = LineItem("widget", Decimal("10.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_10_qualifies_for_bulk_discount(self):
        """Quantity greater than 10 should qualify for bulk discount. (Req 1.2)"""
        item = LineItem("widget", Decimal("10.00"), 11)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_9_does_not_qualify_for_bulk_discount(self):
        """Quantity of 9 should not qualify for bulk discount. (Req 1.3)"""
        item = LineItem("widget", Decimal("10.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_1_does_not_qualify_for_bulk_discount(self):
        """Quantity of 1 should not qualify for bulk discount. (Req 1.3)"""
        item = LineItem("widget", Decimal("10.00"), 1)
        assert qualifies_for_bulk_discount(item) is False


class TestBulkDiscountCalculation:
    """Tests for the bulk discount amount calculation."""

    @pytest.mark.l4("C-8764baca")
    def test_discount_for_quantity_exactly_10(self):
        """5% discount should apply for quantity of exactly 10. (Req 1.1)"""
        # Total = 10.00 * 10 = 100.00, 5% = 5.00
        item = LineItem("widget", Decimal("10.00"), 10)
        assert calculate_bulk_discount(item) == Decimal("5.00")

    @pytest.mark.l4("C-e4015f6b")
    def test_discount_for_quantity_greater_than_10(self):
        """5% discount should apply for quantity greater than 10. (Req 1.2)"""
        # Total = 10.00 * 15 = 150.00, 5% = 7.50
        item = LineItem("widget", Decimal("10.00"), 15)
        assert calculate_bulk_discount(item) == Decimal("7.50")

    @pytest.mark.l4("C-4284227d")
    def test_discount_for_non_qualifying_item_is_zero(self):
        """Non-qualifying items should return zero discount. (Req 1.3)"""
        item = LineItem("widget", Decimal("10.00"), 9)
        assert calculate_bulk_discount(item) == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounds_half_up_to_cents(self):
        """Discount should be rounded half-up to 0.01. (Req 1.4)"""
        # Total = 2.50 * 10 = 25.00, 5% = 1.25
        # Using a price that produces a result needing rounding: 2.51 * 10 = 25.10, 5% = 1.255 -> 1.26
        item = LineItem("widget", Decimal("2.51"), 10)
        assert calculate_bulk_discount(item) == Decimal("1.26")

    @pytest.mark.l4("C-1caf4da3")
    def test_discount_rounds_half_up_for_midpoint(self):
        """Midpoint values should round up. (Req 1.4)"""
        # Total = 2.50 * 10 = 25.00, 5% = 1.25 (exact, no rounding needed)
        # Use a price that gives exactly midpoint: 2.50 * 10 = 25.00, 5% = 1.25
        # For midpoint: need value where 5% ends in exactly .005
        # 2.51 * 10 = 25.10, 5% = 1.255 -> should round to 1.26
        item = LineItem("widget", Decimal("2.51"), 10)
        # This test ensures half-up rounding at the midpoint
        assert calculate_bulk_discount(item) == Decimal("1.26")

